 short_demos=[
  ['Discuss your current AI use and starting assumptions.','Ask the clause question using current evidence.','Compare the response with the complete clause.','Choose one firm task and a success test.'],
  ['Sort document descriptions and discuss labels.','Trace inputs through the learned network.','Compare a query with clause candidates.','Distinguish an upload from a training update.'],
  ['Repeat the same supplied-source task three times.','Compare the long source with a focused excerpt.','Ask for a fee the evidence does not establish.','Score the actual results and retain the prompts.'],
  ['Inspect the actual account and data terms.','Compare a vague request with a professional brief.','Apply Variant A: an unrelated share-sale buyer.','Check the result and record a procurement question.'],
  ['Inventory systems, formats, owners and access.','Compare the original, synthetic scan and observed OCR.','Mark omissions against the authoritative page.','Record corrections, provenance and update responsibilities.'],
  ['Inspect the 40-document library and its versions.','Run the available search route; label its method.','Test current sources, missing evidence and access.','Score retrieval and answer fidelity separately.'],
  ['Read the historical court’s reasoning and orders.','Check the provision and edition references.','Run research where account access permits.','Audit the memo’s claims, sources and remaining gaps.'],
  ['Extract parties, roles and obligations.','Repair all three flawed findings.','Apply Variant B: assignment of the agreement.','Draft one justified customer-side amendment.'],
  ['Inspect the model request and actual lookup.','Check host permissions, arguments and evidence.','Test unknown IDs, injection and configured limits.','Test approval, changed fields and rejection.'],
  ['Reconcile the small files independently.','Investigate the larger ledger and period differences.','Separate evidence checks from tax conclusions.','Test local preparation, approval and uncertain status.'],
  ['Adapt the worked three-risk register.','Examine unequal errors across source collections.','Run the restricted-matter incident for 20 minutes.','Draft a use rule and restart conditions.'],
  ['Repeat the diagnostic with changed examples.','Adapt the worked proposal to one candidate task.','Check cost, review effort and the stress case.','Agree proposed owners and staged decision points.']]
 explanations={
  'Token':'Break a sentence into model input units. A unit can be a word, subword or punctuation; boundaries depend on the tokenizer. Numeric IDs name units and are not meaning scores.',
  'Embedding':'Imagine assigning a coordinate list to a clause and a question. A compatible embedding model lets retrieval compare those lists. A two-dimensional drawing is a projection, not the actual geometry or proof of legal equivalence.',
  'Agent':'Separate proposing a next operation from executing it. The model can choose a permitted lookup based on the result so far. The host must reject an operation outside the authorised task; a request is not permission.',
  'Training':'A learner adjusts numerical parameters to reduce an objective over examples. New examples can alter the mapping. Test on unseen relevant data because fitting the examples does not prove generalisation.',
  'Generative AI':'The system produces content, such as a draft, from learned patterns and supplied context. The generated wording can be new while its factual claims remain unsupported. Compare the draft with the evidence.',
  'Named entity recognition':'Point to each organisation name and date, then distinguish the category label from the contractual role. A model can identify Equator as an organisation without establishing which obligations it owes.',
 }
 misconceptions=[
  [('AI means ChatGPT','Use the task map: arithmetic, classification, retrieval and generation need different mechanisms.'),('A fluent answer is sufficient','Read the two consent answers beside the complete clause; identify the missing exception.'),('Internal always means exempt','Ask for ownership and continued responsibility; the base facts do not establish both.')],
  [('Near token IDs mean similar words','Change arbitrary IDs without changing words, then return to numerical representations.'),('Uploading is training','Separate a parameter update from supplying today’s evidence during inference.'),('Similar clauses have identical legal effect','Change not to its opposite and inspect meaning despite similar vocabulary.')],
  [('A 70% token score is 70% truth','The invented chart predicts a continuation, not the correctness of advice.'),('More context guarantees accuracy','Compare the complete source with the actual answer and inspect the missing-fee test.'),('Three models agreeing is verification','Open the authoritative passage; repeated assertions do not supply an absent fee.')],
  [('A paid plan permits client data','Inspect the actual account terms, processing and firm authority separately.'),('A citation proves the finding','Read the supporting passage and check its role, edition and qualification.'),('A better prompt repairs a missing source','Ask which signed document establishes the claim; request it if absent.')],
  [('A PDF is necessarily searchable text','Compare the page image and encoded text, then inspect the observed OCR.'),('OCR success means complete extraction','Check the negation, exception, layout and source location independently.'),('Metadata is administrative only','Mis-tag a matter in discussion and ask which user might receive the wrong passage.')],
  [('RAG means the model was trained on firm files','Follow the index and question-time evidence paths as separate operations.'),('A stronger model repairs wrong-version retrieval','Give it v1 only and ask where the absent exception could be established.'),('An embedding score determines the legal answer','Inspect the retrieved clause and its conditions after ranking.')],
  [('A submission is the court’s finding','Read Ground5 and the disposition in the original judgment; label each speaker.'),('A section number is enough','Compare the two edition references and record Act, edition, date and proposition.'),('The historical case decides Victoria’s facts','List the different parties, periods, service terms and current-law questions.')],
  [('Recognising a name identifies its obligations','Move from the organisation label to clause2’s actor, action and condition.'),('Assignment is the same as change of control','Compare VariantB with the actual clause; the extract does not answer assignment.'),('A realistic fee can fill the schedule gap','Point to clause4 and request the signed schedule; drafting cannot establish an agreed amount.')],
  [('A prompt alone enforces authority','Inspect the denied unknown-ID trace and the host’s argument checks.'),('A connected tool proves an agent ran','Show the actual model request, host execution and returned observation.'),('Human review is a final checkbox','Decline or change a field in the local demonstration and confirm the dependent action is held.')],
  [('The 18m difference is unpaid tax','Identify the receipts file and the assumptions behind a teaching receivable.'),('Same amount means duplicate','Compare distinct IDs with the repeated INV-003 identity and supporting reference.'),('Timeout means retry immediately','Inspect the uncertain local status; repeating may duplicate an action already recorded.')],
  [('No-training settles confidentiality','Separate training, retention, access, location, contracts and professional permission.'),('A reviewer removes every risk','Ask whether they had evidence, time, competence and a real ability to stop the action.'),('A generic policy is enough','Assign a control owner and test the restricted-matter incident before restart.')],
  [('Released minutes are cash savings','Separate capacity, demand, avoidable cost and actual revenue effects.'),('A good demo justifies expansion','Use representative cases, costs, access failures and the stress scenario.'),('Day90 means automatic deployment','Require an evidence-based expand, revise or stop decision and actual firm approval.')]
 ]
 for i,d in enumerate(c):
  n=i+1;d['session']=n
  label,q,a=recalls[i];d['bridge']=q;focus,questions,expected=checks[i]
  d['understanding_check']={'focus':focus,'questions':questions,'expected':expected}
  d['misconceptions']=[{'wrong':a,'response':b} for a,b in misconceptions[i]]
  intro=[item(d['title'],[d['aim']],f'I will ask: {q} I will record the learner’s explanation before showing the answer. {a}',q,a,'cover'),item(label,[q,d['aim']],f'Ask without showing the prior result. {a} Invite a reason, then connect the answer to today’s question.',q,a,'bridge')]
  end=[item('Our in-class work',short_demos[i],'Use the run-sheet. I demonstrate the first example; the learner predicts, chooses evidence and checks the changed example. Save actual outputs or mark the step unexecuted.','Before we begin: '+d['demo'][0],d['expected'],'workshop'),
   item('What we can conclude',[d['expected'],d['risk']],'Have the learner explain the conclusion before I summarise it. Compare the actual result with the model answer and preserve unresolved questions.','Which part of today’s result remains unverified?',d['risk'],'debrief'),
   item('The firm decision',[d['decision']],'Record a proposed owner and one condition before proceeding. This is a class decision record, not firm authorisation.','What evidence would change this proposed decision?',d['decision']+' Revisit if the evidence, quality or permitted scope changes.','decision'),
   item('Check understanding',questions,'Ask these changed-fact questions before opening the answer key. '+expected,focus,expected,'close')]
  d['slides']=intro+d['slides']+end
  d['core_slides']=list(range(1,len(d['slides'])+1))
  for x in d['optional']:x['optional']=True;d['slides'].append(x)
  d['optional_slides']=list(range(len(d['core_slides'])+1,len(d['slides'])+1));d['reference_slides']=[]
  names=['Recall or entry diagnostic','Concepts and explanation','Worked demonstration','Break','Guided application and tests','Firm decision and understanding','Buffer and recap']
  d['timing']=list(zip(names,allocations[i]));assert sum(allocations[i])==120
  d['run_sheet']=[
   {'block':names[0],'minutes':allocations[i][0],'slides':[1,2],'action':q,'evidence':'A recorded explanation before the model answer.'},
   {'block':names[1],'minutes':allocations[i][1],'slides':list(range(3,len(d['core_slides'])-3)),'action':'Teach the essential explanations in order; combine related slides into one conversation. Optional slides are not scheduled.','evidence':'A correct explanation of the mechanism and its limitation.'},
   {'block':names[2],'minutes':allocations[i][2],'slides':[len(d['core_slides'])-3],'action':'I operate the first two demonstration steps: '+' '.join(d['demo'][:2]),'evidence':'Actual output saved, or unavailable step marked unexecuted.'},
   {'block':names[3],'minutes':allocations[i][3],'slides':[],'action':'Pause.','evidence':''},
   {'block':names[4],'minutes':allocations[i][4],'slides':[len(d['core_slides'])-3],'action':'The learner directs the changed example: '+' '.join(d['demo'][2:]),'evidence':'Source-linked correction and rubric decision.'},
   {'block':names[5],'minutes':allocations[i][5],'slides':list(range(len(d['core_slides'])-2,len(d['core_slides'])+1)),'action':d['decision']+' Then ask: '+focus,'evidence':'A proposed firm decision and a supported transfer answer.'},
   {'block':names[6],'minutes':allocations[i][6],'slides':[],'action':'Recover from setup issues or revisit one explanation. Agree any extra time; do not convert unfinished work to homework.','evidence':'Clarification recorded before the next class.'}]
  # Many essential slides support the worked case; they are not all lecture slides.
  d['concept_slides']=list(range(3,concept_ends[i]+1))
  application=list(range(concept_ends[i]+1,len(d['core_slides'])-3));split=(len(application)+1)//2
  d['run_sheet'][1]['slides']=d['concept_slides']
  d['run_sheet'][2]['slides']=application[:split]+[len(d['core_slides'])-3]
  d['run_sheet'][4]['slides']=application[split:]+[len(d['core_slides'])-3]
  if n==1:
   d['run_sheet'][0]['action']='Use Entry and Exit Diagnostic.csv orally before the explanations. Record the learner’s reasons and current AI use.'
   d['run_sheet'][2]['action']='I give the assistant the current clause and ask the consent question. Retain the actual response, compare it with the source and identify the rule, exception and missing facts.'
  for j,x in enumerate(d['slides']):
   if x['title'] in explanations:x['explain']=explanations[x['title']]
   x['explain']=x['explain'].replace('Connect this explanation to the matter example and ask the question before showing the expected answer.','Ask for a reason before reading the source-based answer.')
   nxt=d['slides'][j+1]['title'] if j+1<len(d['slides']) and not d['slides'][j+1].get('optional') else (('Session '+str(n+1)+': '+c[i+1]['title']) if n<12 else 'Keep the proposal and the decision record for the firm’s review')
   if x.get('optional'):nxt='Return to the essential session conclusion; explore this only if useful'
   chosen=misconceptions[i][j%3]
   misconception=x.get('misconception') or ('Likely confusion: '+chosen[0]+'. I will clarify: '+chosen[1]+' Then return to this slide’s question: '+x['question']+' A supported answer should establish: '+x['answer'])
   x['rescue']=misconception
   x['note']=f"Purpose: {d['aim']}\n\nI will explain: {x['explain']}\n\nAsk: {x['question']}\n\nExpected answer: {x['answer']}\n\nIf partly correct: {misconception}\n\nCheck evidence: identify the supplied source, the actual observed output and any gap before agreeing a conclusion.\n\nTransition: {nxt}.\n\nTeaching status: "+('Optional exploration; not included in the 120-minute plan.' if x.get('optional') else 'Essential sequence; use the session run-sheet.')+'\n\nSources: '+' '.join(x['refs'])+'\nFictional client matter; public authorities are identified separately. All required work happens in class.'
  d.pop('optional',None)
